"use strict";
GUIDE_DATA_VI.sections.push({"id":"g138","part":14,"title":"Các Phương thức Triển khai Thay đổi CNTT (IT Change Delivery Methods)","blocks":[{"level":1,"text":"Các Phương thức Triển khai Thay đổi CNTT Khác nhau (Different IT Change Delivery Methods)"},{"level":2,"text":"Khung giờ Bảo trì (Maintenance Windows)"},{"level":2,"text":"Là các khoảng thời gian hệ thống CNTT được đưa vào trạng thái offline để bảo trì hoặc phát hành mới"},{"level":2,"text":"Bằng cách tạo một timebox nơi nhiều nhóm có thể thực hiện chức năng trên một hệ thống trong khung giờ bảo trì, các thay đổi có chủ đích có thể được gom lại, giảm thời gian ngừng hoạt động"},{"level":2,"text":"Hệ thống CNTT đóng vai trò quan trọng trong hoạt động của một tổ chức"},{"level":2,"text":"Việc truy cập các thông tin quan trọng như dữ liệu khách hàng, bảng lương, website, đơn hàng và thông số kỹ thuật sản phẩm phụ thuộc vào công nghệ"},{"level":2,"text":"Bản phát hành (Releases)"},{"level":2,"text":"Bao gồm mã nguồn của sản phẩm, gồm một tập hợp các cải tiến và điều chỉnh phần mềm"},{"level":2,"text":"Thông báo cho Khách hàng (Customer Notifications)"},{"level":2,"text":"Khách hàng phải được thông báo về mọi khung giờ bảo trì vì họ có thể gặp gián đoạn và mất dịch vụ"},{"level":2,"text":"Nhóm kỹ thuật CNTT có nhiều phương thức thông báo cho khách hàng về khung giờ bảo trì"},{"level":2,"text":"Banner hoặc Thông báo (Banner or Notice)"},{"level":2,"text":"Tin nhắn hoặc Thông báo đẩy (Message or Push Notification)"},{"level":2,"text":"Email"},{"level":2,"text":"Tin nhắn văn bản (Text)"},{"level":2,"text":"Mạng xã hội (Social Media)"},{"level":2,"text":"Điều quan trọng cần lưu ý là không phải mọi thay đổi CNTT và phần mềm đều cần thông báo cho khách hàng"},{"level":1,"text":"Thư viện Cơ sở hạ tầng CNTT (IT Infrastructure Library - ITIL) phân loại thay đổi thành ba loại"},{"level":2,"text":"Thay đổi Chuẩn (Standard Change)"},{"level":2,"text":"Các thay đổi lặp lại với chính sách và quy trình đã thiết lập, không cần phê duyệt thêm"},{"level":2,"text":"Thay đổi Thông thường (Normal Change)"},{"level":2,"text":"Các điều chỉnh không có quy trình cố định và không xảy ra thường xuyên, nhưng cũng không phải thay đổi khẩn cấp"},{"level":2,"text":"Thay đổi Khẩn cấp (Emergency Change)"},{"level":2,"text":"Các sự kiện phục hồi không được lên kế hoạch, thường không cho phép thời gian thông báo trước"},{"level":1,"text":"Các thay đổi hạ tầng được truyền thông qua cùng các kênh như thay đổi phần mềm"},{"level":1,"text":"Nhìn chung, khách hàng nên được thông báo nếu thay đổi tác động đến trải nghiệm người dùng, quyền truy cập, cài đặt tài khoản hoặc mối quan hệ của họ với công ty"},{"level":2,"text":"Ví dụ bao gồm các thay đổi đối với những mục sau"},{"level":2,"text":"Quy trình Đăng nhập Người dùng (User Login Process)"},{"level":2,"text":"Yêu cầu Mật khẩu (Password Requirements)"},{"level":2,"text":"Hợp đồng (Contracts)"},{"level":2,"text":"Giá Gói đăng ký (Subscription Prices)"},{"level":2,"text":"Điều hướng Người dùng (User Navigation)"},{"level":1,"text":"Khách hàng không cần được thông báo về các thay đổi đối với quy trình làm việc nội bộ hoặc lưu trữ dữ liệu nếu khách hàng không nhận ra được và pháp luật không yêu cầu"}]},{"id":"g139","part":14,"title":"Giảm thiểu Rủi ro Thay đổi CNTT (IT Change Risk Mitigation)","blocks":[{"level":1,"text":"2 Dạng Chính của Kế hoạch Dự phòng (2 Primary Forms of Backup Plans)"},{"level":2,"text":"Kế hoạch Rollback (Rollback Plan)"},{"level":2,"text":"Đảm bảo nhóm đã chuẩn bị để khôi phục phiên bản trước của hệ thống trong trường hợp bản phát hành thất bại"},{"level":2,"text":"Đây là kế hoạch dự phòng (contingency plan) cần được xây dựng trước"},{"level":2,"text":"Kế hoạch rollback đóng vai trò là lựa chọn cuối cùng"},{"level":2,"text":"Kiểm tra Sau triển khai (Post-Production Validation)"},{"level":2,"text":"Cần thiết để xác nhận phần mềm trong môi trường production đang hoạt động như dự định"},{"level":2,"text":"Nhóm QA kiểm thử mọi thay đổi trong môi trường kiểm thử khớp chính xác với môi trường production"},{"level":2,"text":"Các quy trình triển khai phải diễn ra theo một trình tự cụ thể"},{"level":2,"text":"Trong quá trình kiểm tra, kỹ sư QA đi theo cùng đường dẫn như khi họ kiểm thử phần mềm lần đầu"},{"level":2,"text":"Hoàn thành các bài kiểm thử và ghi lại kết quả"},{"level":2,"text":"Báo cáo kết quả và xác định các vấn đề và lỗi"}]},{"id":"g140","part":14,"title":"Môi trường IT","blocks":[{"level":1,"text":"Kiểm soát thay đổi tại chỗ (on-premises change control) là một quy trình thủ công hơn so với các thay đổi trên đám mây"},{"level":1,"text":"Các triển khai đám mây sử dụng tự động hóa (automation) để tăng hiệu quả, dẫn đến phát hành thường xuyên hơn"},{"level":1,"text":"Trong giải pháp tại chỗ, nhân viên vận hành tự tạo và quản lý thủ công các bản sao lưu dữ liệu để hỗ trợ kế hoạch khôi phục (rollback plan)"},{"level":1,"text":"Các mô hình đám mây tích hợp sẵn các kiểm tra cấu hình và bảo mật"},{"level":1,"text":"Điện toán đám mây áp dụng mô hình trách nhiệm chung (shared responsibility model) cho bảo mật"},{"level":1,"text":"Tổ chức phải chịu trách nhiệm về các chính sách nội bộ, bảo mật dữ liệu và cấu hình hệ thống của mình"},{"level":1,"text":"Ngược lại, hạ tầng tại chỗ đặt tổ chức vào vị trí kiểm soát toàn bộ các khía cạnh bảo mật, dẫn đến trách nhiệm lớn hơn đáng kể"},{"level":1,"text":"Lưu ý thêm, các tổ chức có thể cải thiện các triển khai tại chỗ bằng tự động hóa quy trình và các tích hợp bổ sung"},{"level":1,"text":"Môi trường phát triển phần mềm (software development environment) là nơi phần mềm được phát triển, kiểm thử và triển khai"},{"level":2,"text":"Môi trường này cũng có thể được gọi là \"stage\" hoặc \"tier\""},{"level":1,"text":"Các tổ chức có thể tạo bao nhiêu stage tùy theo nhu cầu để bao phủ toàn bộ chu kỳ DevOps, nhưng thông thường ba loại tier cơ bản được sử dụng"},{"level":2,"text":"Development Tier là nơi phần mềm được tạo ra, và nó chỉ khả dụng cho một người dùng đơn lẻ tại máy cục bộ"},{"level":2,"text":"Beta Tier là môi trường kiểm thử nơi các nhà phát triển đẩy mã (code) từ môi trường phát triển của mình sang để kiểm thử các thay đổi đã thực hiện"},{"level":2,"text":"Production Tier là môi trường chạy thật (live) mà người dùng cuối có thể truy cập"},{"level":1,"text":"Các mô hình đám mây cũng cung cấp các tính năng tích hợp sẵn"},{"level":2,"text":"Sao lưu dữ liệu (Data Backup)"},{"level":2,"text":"Kiểm soát phiên bản (Version Control)"},{"level":2,"text":"Khôi phục (Roll Back)"},{"level":2,"text":"Kiểm tra bảo mật (Security Checks) và Quản lý hiệu suất (Managing Performance)"}]},{"id":"g141","part":15,"title":"Quản lý hiệu suất","blocks":[{"level":1,"text":"Chi phí và tiến độ của dự án không cố định"},{"level":1,"text":"Biểu đồ đốt cháy phạm vi (Scope Burndown Chart)"},{"level":2,"text":"Theo dõi tiến độ hoàn thành phạm vi của dự án, giúp PM giám sát công việc và xác định các vấn đề hoặc sự chậm trễ"},{"level":1,"text":"Biểu đồ đốt cháy ngân sách (Budget Burndown Chart)"},{"level":2,"text":"Theo dõi chi phí của dự án so với ngân sách"},{"level":1,"text":"Phân tích chênh lệch (Gap Analysis)"},{"level":2,"text":"Dùng để xác định các chênh lệch giữa kết quả kỳ vọng và kết quả thực tế"},{"level":1,"text":"Dự trữ dự phòng (Contingency Reserve)"},{"level":2,"text":"Quy trình sử dụng các nguồn lực đã dành riêng trong dự án để xử lý các rủi ro hoặc thay đổi không lường trước"},{"level":1,"text":"Quản trị giá trị thu được (Earned Value Management - EVM)"},{"level":2,"text":"Phương pháp giám sát sử dụng giá trị kế hoạch, giá trị thu được và chi phí thực tế để theo dõi hiệu suất dự án"},{"level":1,"text":"Ước tính khi hoàn thành (Estimate at Completion - EAC) và Ước tính để hoàn thành (Estimate to Complete - ETC) là các chỉ số quan trọng trong quản trị giá trị thu được"},{"level":2,"text":"4 phương pháp tiêu chuẩn để tính ETC"},{"level":2,"text":"Từ dưới lên (Bottom-up)"},{"level":2,"text":"Tỷ lệ dự toán (Budgeted rate)"},{"level":2,"text":"Chỉ số hiệu suất chi phí (Cost Performance Index - CPI)"},{"level":2,"text":"Kết hợp CPI và Chỉ số hiệu suất tiến độ (Schedule Performance Index - SPI)"},{"level":1,"text":"Tiến độ dự án có thể được duy trì ở các mức độ thông tin khác nhau"},{"level":2,"text":"Điều hành (Executive)"},{"level":2,"text":"Mốc quan trọng (Milestone)"},{"level":2,"text":"Chi tiết (Detailed)"}]},{"id":"g142","part":15,"title":"Biểu đồ đốt cháy phạm vi và ngân sách","blocks":[{"level":1,"text":"Biểu đồ đốt cháy phạm vi (Scope Burndown Chart)"},{"level":2,"text":"Đồ thị trực quan theo dõi tiến độ hoàn thành phạm vi của dự án theo thời gian"},{"level":2,"text":"Biểu đồ hiển thị công việc còn lại (theo các hạng mục phạm vi) cần hoàn thành trên trục tung và thời gian trên trục hoành"},{"level":2,"text":"Biểu đồ đốt cháy có thể được dùng để xác định đội nhóm đang đi trước hay chậm tiến độ"},{"level":1,"text":"Biểu đồ đốt cháy ngân sách (Budget Burndown Chart)"},{"level":2,"text":"Biến thể của biểu đồ đốt cháy theo dõi tiến độ chi phí của dự án theo thời gian"},{"level":2,"text":"Biểu đồ đốt cháy ngân sách so sánh tốc độ chi tiêu với tốc độ của dự án"},{"level":1,"text":"Điểm khác biệt chính giữa biểu đồ đốt cháy ngân sách và các loại biểu đồ đốt cháy khác"},{"level":2,"text":"Biểu đồ đốt cháy giờ công việc (Task Hours Burndown)"},{"level":2,"text":"Có số giờ công việc còn lại ít hơn dự kiến ban đầu vì điều đó cho thấy dự án đang đi trước tiến độ"},{"level":2,"text":"Biểu đồ đốt cháy ngân sách (Budget Burndown)"},{"level":2,"text":"Ngân sách thực tế còn lại phải bằng hoặc cao hơn ngân sách mục tiêu"},{"level":1,"text":"PM tương tác với biểu đồ đốt cháy ngân sách ít nhất hàng tuần để đánh giá tốc độ đốt cháy (burn rate) của dự án"},{"level":2,"text":"PM quản lý hiệu suất nhà cung cấp, yếu tố có thể ảnh hưởng đáng kể đến chi phí, và họ tham gia vào việc lựa chọn nhà cung cấp, phê duyệt hoặc quản lý việc sử dụng nguồn lực, thay đổi phạm vi và sử dụng bộ đệm (buffer utilization)"},{"level":1,"text":"Biểu đồ đốt cháy phạm vi giúp PM hiểu cách tiến độ hoàn thành công việc ảnh hưởng đến phạm vi dự án"},{"level":1,"text":"Biểu đồ đốt cháy ngân sách giúp PM hiểu cách chi phí của dự án ảnh hưởng đến ngân sách dự án"}]},{"id":"g143","part":15,"title":"Phân tích chênh lệch hiệu suất dự án","blocks":[{"level":1,"text":"Thực hiện phân tích chênh lệch (gap analysis) có thể giúp xác định tại sao chênh lệch tồn tại, sau đó là phân tích nguyên nhân gốc rễ (root cause analysis) để xác định nguyên nhân thực sự của chênh lệch"},{"level":1,"text":"Phân tích chênh lệch cho phép tự do điều chỉnh một trong hai tham số, chẳng hạn như cải thiện hiệu suất hoặc thay đổi mục tiêu"},{"level":1,"text":"Các ước tính quá hào phóng có thể khiến dữ liệu kém tin cậy, vì vậy có thể ước tính lại công việc để tạo ra một kế hoạch thực tế hơn"},{"level":1,"text":"Biểu đồ đốt cháy có thể xác định một chênh lệch, nhưng nó không tiết lộ nguyên nhân của nó"},{"level":1,"text":"Điều quan trọng cần lưu ý là việc giải quyết các chênh lệch có thể tốn thời gian, và nên kỳ vọng cải thiện dần dần"},{"level":1,"text":"Phân tích chênh lệch có thể là một kỹ thuật hữu ích trong các dự án agile để xác định sự khác biệt giữa trạng thái hiện tại và trạng thái mong muốn và định hướng phát triển các giải pháp"},{"level":1,"text":"Bằng cách dùng phân tích chênh lệch để xác định và ưu tiên các vấn đề then chốt, đội nhóm có thể tập trung nỗ lực vào những cải tiến có tác động lớn nhất"}]},{"id":"g144","part":15,"title":"Sử dụng dự trữ dự phòng","blocks":[{"level":1,"text":"Sử dụng dự trữ dự phòng (Contingency Reserve Utilization)"},{"level":2,"text":"Quy trình sử dụng các dự trữ dự phòng trong dự án để xử lý các rủi ro hoặc thay đổi bất ngờ có thể ảnh hưởng đến phạm vi, tiến độ hoặc ngân sách dự án"},{"level":1,"text":"Trong dự án CNTT, việc sử dụng dự trữ dự phòng có thể được dùng theo nhiều cách"},{"level":2,"text":"Xử lý các rủi ro không lường trước"},{"level":2,"text":"Quản lý các thay đổi"},{"level":2,"text":"Giảm thiểu sự chậm trễ tiến độ"},{"level":1,"text":"Để sử dụng dự trữ dự phòng hiệu quả, quản lý dự án phải hiểu rõ các rủi ro và sự không chắc chắn của dự án, và xây dựng kế hoạch xử lý chúng"},{"level":1,"text":"Bằng cách chủ động phân bổ nguồn lực và xây dựng kế hoạch xử lý các vấn đề tiềm ẩn, quản lý dự án có thể giúp đảm bảo thành công của dự án và hoàn thành các mục tiêu dự án"},{"level":1,"text":"Việc sử dụng các dự trữ dự phòng không làm thay đổi đường cơ sở chi phí dự án (project cost baseline)"}]},{"id":"g145","part":15,"title":"Quản trị giá trị thu được","blocks":[{"level":1,"text":"Quản trị giá trị thu được (Earned Value Management - EVM)"},{"level":2,"text":"Một phương pháp giám sát dùng để theo dõi hiệu suất dự án dựa trên ba giá trị then chốt giám sát hiệu suất tiến độ và chi phí"},{"level":2,"text":"Ba giá trị được dùng trong EVM"},{"level":2,"text":"Giá trị kế hoạch (Planned Value - PV)"},{"level":2,"text":"Đại diện cho chi phí mục tiêu và tiến độ"},{"level":2,"text":"Giá trị thu được (Earned Value - EV)"},{"level":2,"text":"Đại diện cho tiến độ thực tế"},{"level":2,"text":"Chi phí thực tế (Actual Cost - AC)"},{"level":2,"text":"Đại diện cho chi phí thực tế"},{"level":1,"text":"Ngân sách khi hoàn thành (Budget at Completion - BAC)"},{"level":2,"text":"Bằng đường cơ sở chi phí của dự án"},{"level":1,"text":"Các chỉ số cơ bản của Quản trị giá trị thu được (EVM) có thể được tính như sau"},{"level":2,"text":"Giá trị kế hoạch (Planned Value - PV)"},{"level":2,"text":"Đại diện cho ngân sách được phê duyệt phân bổ cho công việc đã lên lịch"},{"level":2,"text":"PV = (phần trăm công việc đã lên lịch theo kế hoạch) x (tổng chi phí dự toán của công việc)"},{"level":2,"text":"Giá trị thu được (Earned Value - EV)"},{"level":2,"text":"Đại diện cho chi phí dự toán của công việc thực tế đã thực hiện"},{"level":2,"text":"EV = (phần trăm công việc thực tế đã hoàn thành) X (tổng chi phí dự toán của công việc)"},{"level":2,"text":"Chi phí thực tế (Actual Cost - AC)"},{"level":2,"text":"Đại diện cho chi phí thực tế phát sinh khi thực hiện công việc"},{"level":1,"text":"Các chỉ số EVM như chênh lệch tiến độ (schedule variance - SV), chênh lệch chi phí (cost variance - CV), chỉ số hiệu suất tiến độ (schedule performance index - SPI) và chỉ số hiệu suất chi phí (cost performance index - CPI) có thể được tính toán"}]},{"id":"g146","part":15,"title":"Các chỉ số hiệu suất chi phí và tiến độ","blocks":[{"level":1,"text":"Quản trị giá trị thu được (Earned Value Management - EVM)"},{"level":2,"text":"Một phương pháp giám sát dùng để theo dõi hiệu suất dự án, dựa trên ba giá trị then chốt giám sát hiệu suất tiến độ và chi phí"},{"level":2,"text":"Ba giá trị được dùng trong EVM"},{"level":2,"text":"Giá trị kế hoạch (Planned Value - PV)"},{"level":2,"text":"Đại diện cho chi phí mục tiêu và tiến độ"},{"level":2,"text":"Giá trị thu được (Earned Value - EV)"},{"level":2,"text":"Đại diện cho tiến độ thực tế"},{"level":2,"text":"Chi phí thực tế (Actual Cost - AC)"},{"level":2,"text":"Đại diện cho chi phí thực tế"},{"level":1,"text":"Chênh lệch chi phí (Cost Variance - CV)"},{"level":2,"text":"Đo lường sự chênh lệch giữa giá trị thu được và chi phí thực tế"},{"level":2,"text":"Chênh lệch chi phí = Giá trị thu được – Chi phí thực tế"},{"level":2,"text":"CV > 0"},{"level":2,"text":"Dự án đang dưới ngân sách"},{"level":2,"text":"CV = 0"},{"level":2,"text":"Dự án đang chi đúng mức"},{"level":2,"text":"CV < 0"},{"level":2,"text":"Dự án đang vượt ngân sách"},{"level":1,"text":"Chỉ số hiệu suất chi phí (Cost Performance Index - CPI)"},{"level":2,"text":"So sánh giá trị thu được với chi phí thực tế"},{"level":2,"text":"Chỉ số hiệu suất chi phí = Giá trị kỳ vọng / Chi phí thực tế"},{"level":2,"text":"CPI > 1"},{"level":2,"text":"Dự án đang dưới ngân sách"},{"level":2,"text":"CPI = 1"},{"level":2,"text":"Dự án đang chi đúng mức"},{"level":2,"text":"CPI < 1"},{"level":2,"text":"Dự án đang vượt ngân sách"},{"level":1,"text":"Chênh lệch tiến độ (Schedule Variance - SV)"},{"level":2,"text":"Đo lường sự chênh lệch giữa giá trị thu được và giá trị kế hoạch"},{"level":2,"text":"Chênh lệch tiến độ dương nghĩa là dự án hoàn thành công việc nhanh hơn kỳ vọng"},{"level":2,"text":"Chênh lệch tiến độ = Giá trị kỳ vọng – Giá trị kế hoạch"},{"level":2,"text":"SV > 0"},{"level":2,"text":"Dự án đang đi trước tiến độ"},{"level":2,"text":"SV = 0"},{"level":2,"text":"Dự án đang đúng nhịp với các ước tính"},{"level":2,"text":"SV < 0"},{"level":2,"text":"Dự án đang chậm tiến độ"},{"level":1,"text":"Chỉ số hiệu suất tiến độ (Schedule Performance Index - SPI)"},{"level":2,"text":"So sánh giá trị kỳ vọng và giá trị kế hoạch"},{"level":2,"text":"Chỉ số hiệu suất tiến độ = Giá trị kỳ vọng / Giá trị kế hoạch"},{"level":2,"text":"SPI > 1"},{"level":2,"text":"Dự án đang đi trước tiến độ"},{"level":2,"text":"SPI < 0"},{"level":2,"text":"Dự án không tạo ra giá trị nhanh như kỳ vọng"}]},{"id":"g147","part":15,"title":"Dự báo hiệu suất","blocks":[{"level":1,"text":"Ước tính khi hoàn thành (Estimate at Completion - EAC)"},{"level":2,"text":"Đo lường dự báo về tổng chi phí của dự án, dựa trên hiệu suất trước đó"},{"level":1,"text":"Ước tính để hoàn thành (Estimate to Complete - ETC)"},{"level":2,"text":"Chi phí dự kiến để hoàn thành phần công việc còn lại của dự án"},{"level":1,"text":"Ước tính khi hoàn thành (EAC) = Chi phí thực tế (AC) + Ước tính để hoàn thành (ETC)"},{"level":1,"text":"4 phương pháp tiêu chuẩn để tính Ước tính để hoàn thành (ETC)"},{"level":2,"text":"Từ dưới lên (Bottom-up)"},{"level":2,"text":"Bao gồm việc chia nhỏ công việc còn lại thành các thành phần nhỏ hơn và ước tính chi phí của từng thành phần riêng lẻ"},{"level":2,"text":"EAC = AC + ETC"},{"level":2,"text":"Trong đó ETC là tổng của tất cả các hoạt động còn lại"},{"level":2,"text":"Tỷ lệ dự toán (Budgeted Rate)"},{"level":2,"text":"Bao gồm việc tính tỷ lệ dự toán cho công việc còn lại và nhân nó với khối lượng công việc còn lại"},{"level":2,"text":"EAC = AC + (BAC – EV)"},{"level":2,"text":"Chỉ số hiệu suất chi phí (Cost Performance Index - CPI)"},{"level":2,"text":"Bao gồm việc sử dụng chỉ số hiệu suất chi phí (CPI) để dự báo chi phí hoàn thành phần công việc còn lại"},{"level":2,"text":"EAC = BAC / CPI"},{"level":2,"text":"Kết hợp CPI và SPI"},{"level":2,"text":"Dùng để dự báo chi phí hoàn thành phần công việc còn lại, có tính đến cả hiệu suất chi phí và hiệu suất tiến độ"},{"level":2,"text":"EAC = AC + ( [BAC-EV] / [CPI * SPI] )"},{"level":1,"text":"Chênh lệch khi hoàn thành (Variance at Completion - VAC)"},{"level":2,"text":"Đo lường tổng chênh lệch mà dự án dự kiến sẽ gặp"},{"level":2,"text":"VAC = BAC – EAC"}]},{"id":"g148","part":15,"title":"Thiết lập lại đường cơ sở và điều chỉnh đường cơ sở","blocks":[{"level":1,"text":"Các đường cơ sở gốc có thể không còn phản ánh chính xác thực tế của dự án"},{"level":1,"text":"Khi các yêu cầu thay đổi được đưa vào dự án, chi phí, phạm vi hoặc ngân sách có thể bị ảnh hưởng"},{"level":1,"text":"Tăng phạm vi dẫn đến tăng chi phí và tiến độ"},{"level":1,"text":"PM chịu trách nhiệm duy trì ngân sách dự án luôn được cập nhật"},{"level":1,"text":"Quy trình cập nhật ngân sách dự án tương tự như quy trình tạo ra nó, sử dụng cùng các công cụ và quy trình"},{"level":1,"text":"Một số lý do phổ biến để cập nhật ngân sách và tiến độ là gì?"},{"level":2,"text":"Khi nhận được yêu cầu thay đổi mới, đội dự án phải đánh giá tác động tiềm ẩn của nó đến ngân sách"},{"level":2,"text":"Phân tích này nên xem xét các thay đổi trong phân bổ nguồn lực và thay đổi về số lượng hoạt động của dự án"},{"level":1,"text":"Việc phê duyệt các yêu cầu thay đổi có thể làm thay đổi ngày kết thúc dự án nếu thay đổi ảnh hưởng đến đường găng (critical path)"},{"level":1,"text":"Các hoạt động khắc phục lỗi (defect) phải được đưa vào tiến độ và ngân sách dự án"},{"level":1,"text":"Khi dự án tiến triển, đội nhóm có thể hiểu rõ hơn về nỗ lực và các hoạt động cần thiết, dẫn đến ước tính được cải thiện"},{"level":2,"text":"Ước tính được cải thiện có thể tác động tích cực hoặc tiêu cực đến tình hình của dự án"},{"level":1,"text":"Thiết lập lại đường cơ sở (Rebaselining) có thể là một hoạt động lặp lại"},{"level":1,"text":"Khi chúng ta nói về việc điều chỉnh tiến độ, những loại lịch trình dự án nào được kỳ vọng?"},{"level":2,"text":"Lịch trình điều hành (Executive Schedule)"},{"level":2,"text":"Phác thảo tiến độ và kết quả của dự án, nhưng nó không bao gồm các hoạt động chi tiết"},{"level":2,"text":"Lịch trình điều hành chỉ thay đổi khi có thay đổi về mốc quan trọng hoặc hoạt động tóm tắt"},{"level":2,"text":"Lịch trình mốc quan trọng (Milestone Schedule)"},{"level":2,"text":"Dùng để giám sát tiến độ của dự án hướng tới các bàn giao"},{"level":2,"text":"Lịch trình mốc quan trọng thay đổi khi có thay đổi về các mốc quan trọng hoặc khi các thay đổi hoạt động dẫn đến các mốc quan trọng mới"},{"level":2,"text":"Lịch trình chi tiết (Detailed Schedule)"},{"level":2,"text":"Phác thảo hoạt động, thời lượng, phụ thuộc và mốc quan trọng của dự án"},{"level":2,"text":"Các thay đổi đối với tiến độ dự án yêu cầu một thay đổi trong lịch trình chi tiết"},{"level":1,"text":"Một lịch trình mốc quan trọng đã cập nhật nên được chuẩn bị mỗi khi có yêu cầu thay đổi"},{"level":1,"text":"Việc cập nhật thường xuyên kế hoạch quản lý dự án, bao gồm cả tiến độ dự án, là thực tiễn tốt, và quản lý dự án nên duy trì tiến độ ít nhất hàng tuần"},{"level":2,"text":"Dưới đây là một số công việc duy trì tiến độ nên được thực hiện thường xuyên"},{"level":2,"text":"Xem xét đường găng (critical path)"},{"level":2,"text":"Xem xét việc sử dụng nguồn lực"},{"level":2,"text":"Xem xét kế hoạch sprint hiện tại"},{"level":2,"text":"Cập nhật tiến độ dự án"},{"level":2,"text":"Công bố các tiến độ dự án đã cập nhật"},{"level":2,"text":"Xem xét các bảng điều khiển dự án"},{"level":2,"text":"Chuẩn bị các báo cáo trạng thái dự án"}]},{"id":"g149","part":15,"title":"Bảng điều khiển dự án","blocks":[{"level":1,"text":"Bảng điều khiển kinh doanh (Business Dashboard)"},{"level":2,"text":"Cung cấp bản tóm tắt trực quan về dữ liệu toàn diện từ nhiều nguồn"},{"level":2,"text":"Tạo bảng điều khiển cho mọi dữ liệu tóm tắt, bao gồm các dự án, sản phẩm, chương trình, phòng ban hoặc đội nhóm"},{"level":1,"text":"KPI đo lường khả năng dự án đạt được các mục tiêu của nó, và nếu hoạt động tốt, bạn có thể giả định rằng dự án đang tiến triển tốt"},{"level":2,"text":"Một dự án nên có 4-10 KPI, bao gồm sự kết hợp giữa các mục tiêu tập trung vào kết quả và các mục tiêu hiệu suất"},{"level":2,"text":"Số lượng người dùng"},{"level":2,"text":"Doanh thu tạo ra"},{"level":2,"text":"Hiệu suất so với ngân sách"},{"level":2,"text":"Chi phí trên mỗi yêu cầu"},{"level":2,"text":"Chênh lệch chi phí (CV)"},{"level":2,"text":"Chênh lệch tiến độ (SV)"},{"level":1,"text":"Một số điểm khác biệt chính giữa bảng điều khiển và báo cáo"},{"level":2,"text":"Bảng điều khiển (Dashboards)"},{"level":2,"text":"Cập nhật liên tục"},{"level":2,"text":"Tương tác"},{"level":2,"text":"Báo cáo (Reports)"},{"level":2,"text":"Cập nhật định kỳ"},{"level":2,"text":"Tĩnh"},{"level":2,"text":"Bao gồm ảnh chụp nhanh của bảng điều khiển nhưng cũng cung cấp thêm thông tin"},{"level":1,"text":"Bảng điều khiển điều hành (Executive Dashboard)"},{"level":2,"text":"Được thiết kế cho quản lý cấp cao và cung cấp cái nhìn tổng quan cấp cao về hiệu suất của tổ chức"},{"level":2,"text":"Đối tượng (Audience)"},{"level":2,"text":"Bảng điều khiển điều hành được thiết kế cho quản lý cấp cao và cung cấp cái nhìn tổng quan cấp cao về hiệu suất của tổ chức"},{"level":2,"text":"Nội dung (Content)"},{"level":2,"text":"Bảng điều khiển điều hành thường hiển thị các KPI và chỉ số quan trọng đối với các mục tiêu chiến lược của tổ chức"},{"level":2,"text":"Trực quan hóa (Visualization)"},{"level":2,"text":"Bảng điều khiển điều hành thường dùng biểu đồ và đồ thị để trình bày dữ liệu theo cách bắt mắt"},{"level":2,"text":"Tương tác (Interactivity)"},{"level":2,"text":"Bảng điều khiển điều hành có thể không tương tác, vì chúng được thiết kế để cung cấp cái nhìn tổng quan cấp cao về hiệu suất của tổ chức"},{"level":1,"text":"Bảng điều khiển đội nhóm (Team Dashboard)"},{"level":2,"text":"Được thiết kế cho các đội nhóm hoặc phòng ban cụ thể và tập trung vào các chỉ số riêng của đội nhóm"},{"level":2,"text":"Đối tượng (Audience)"},{"level":2,"text":"Bảng điều khiển đội nhóm được thiết kế cho các đội nhóm hoặc phòng ban cụ thể và tập trung vào các chỉ số riêng của đội nhóm"},{"level":2,"text":"Nội dung (Content)"},{"level":2,"text":"Bảng điều khiển đội nhóm tập trung vào các chỉ số liên quan đến mục tiêu của đội nhóm, chẳng hạn như sự hài lòng của khách hàng hoặc năng suất đội nhóm"},{"level":2,"text":"Trực quan hóa (Visualization)"},{"level":2,"text":"Bảng điều khiển đội nhóm có thể dùng các hình ảnh trực quan chi tiết hơn, chẳng hạn như bản đồ nhiệt (heat map) hoặc đồ thị tia lửa (sparkline), để hiển thị xu hướng hoặc mẫu hình"},{"level":2,"text":"Tương tác (Interactivity)"},{"level":2,"text":"Bảng điều khiển đội nhóm có thể tương tác nhiều hơn, cho phép các thành viên đội nhóm đi sâu vào các chỉ số hoặc điểm dữ liệu cụ thể"},{"level":1,"text":"Bảng điều khiển quản lý dự án (Project Manager Dashboard)"},{"level":2,"text":"Được thiết kế cho các quản lý dự án và cung cấp dữ liệu riêng của dự án"},{"level":2,"text":"Đối tượng (Audience)"},{"level":2,"text":"Bảng điều khiển quản lý dự án được thiết kế cho các quản lý dự án và cung cấp dữ liệu riêng của dự án"},{"level":2,"text":"Nội dung (Content)"},{"level":2,"text":"Bảng điều khiển quản lý dự án hiển thị dữ liệu riêng của dự án, chẳng hạn như trạng thái dự án, hoàn thành công việc và sử dụng nguồn lực"},{"level":2,"text":"Trực quan hóa (Visualization)"},{"level":2,"text":"Bảng điều khiển quản lý dự án có thể dùng biểu đồ Gantt hoặc dòng thời gian (timeline) để hiển thị tiến độ dự án"},{"level":2,"text":"Tương tác (Interactivity)"},{"level":2,"text":"Bảng điều khiển quản lý dự án thường tương tác nhiều nhất, cho phép các quản lý dự án điều chỉnh kế hoạch dự án hoặc phân bổ nguồn lực khi cần"},{"level":1,"text":"Bảng điều khiển có thể có nhiều hình thức khác nhau, nhưng chúng thường bao gồm các ô đồ họa, danh sách, đồng hồ đo và khối thông tin"},{"level":2,"text":"Nguyên tắc thiết kế của bảng điều khiển"},{"level":2,"text":"Tính trực quan (Intuitiveness)"},{"level":2,"text":"Bảng điều khiển nên được thiết kế sao cho ngay cả người được đào tạo tối thiểu cũng có thể hiểu được thông tin"},{"level":2,"text":"Tính hành động (Actionable)"},{"level":2,"text":"Nó nên chứa thông tin có giá trị giúp chủ sở hữu biết mình cần thực hiện hành động gì trong vòng 30 giây nhìn vào nó"},{"level":2,"text":"Tính liên quan (Relevance)"},{"level":2,"text":"Chúng nên chứa thông tin mà đối tượng cần biết để đưa ra quyết định tốt"},{"level":2,"text":"Tính kịp thời (Timely)"},{"level":2,"text":"Thông tin nên được làm mới ít nhất thường xuyên như mức độ cần thiết"},{"level":1,"text":"Tính ngắn gọn (Brevity): Bảng điều khiển chỉ nên chứa thông tin cần thiết và không nên làm người dùng choáng ngợp với các chỉ số không cần thiết"},{"level":1,"text":"Tính chính xác (Accuracy): Nên dùng dữ liệu chất lượng cao phản ánh thực tế để đưa ra quyết định"},{"level":1,"text":"Tính bền vững (Sustainability): Bảng điều khiển tự động cập nhật khi dữ liệu nguồn được cập nhật là lý tưởng cho việc sử dụng lâu dài Wrapping Up the Project"}]},{"id":"g150","part":16,"title":"Kết thúc dự án","blocks":[{"level":1,"text":"Đội nhóm chuẩn bị các báo cáo cuối cùng, tổ chức các cuộc họp cuối cùng và gửi khảo sát cho dự án"},{"level":1,"text":"Khi đội nhóm gần đến cuối giai đoạn thực thi (Execution), việc bắt đầu lập kế hoạch cho việc kết thúc dự án là rất cần thiết"},{"level":1,"text":"Đội dự án có thể dùng OCM để giảm căng thẳng do thay đổi tạo ra"},{"level":1,"text":"Quản lý thay đổi tổ chức (Organizational Change Management - OCM)"},{"level":2,"text":"Phương pháp có hệ thống để quản lý và triển khai các thay đổi trong một tổ chức"},{"level":1,"text":"Tỷ lệ chấp nhận cao rất quan trọng cho sự thành công của các sáng kiến thay đổi"},{"level":1,"text":"Việc giám sát và củng cố việc chấp nhận thông qua thu thập phản hồi và hỗ trợ liên tục là rất quan trọng"},{"level":1,"text":"Để kết nối hiệu quả với người dùng cuối trong OCM, giao tiếp hiệu quả là chìa khóa"},{"level":2,"text":"Điều này bao gồm giao tiếp thường xuyên và sớm bằng nhiều kênh khác nhau và khuyến khích giao tiếp hai chiều thông qua giờ làm việc mở hoặc khảo sát"},{"level":2,"text":"Các buổi trình diễn (demo), phiên họp nhóm nhỏ và tương tác cá nhân hóa có thể giúp thu thập phản hồi và giải quyết các mối lo ngại"},{"level":1,"text":"Các cuộc họp đánh giá đóng dự án (project closeout reviews) bao gồm việc hoàn tất các hoạt động để chính thức đóng dự án"},{"level":1,"text":"Tài liệu phạm vi dự án nên được xem xét để xác nhận các mục tiêu và bàn giao đã được đáp ứng chưa"},{"level":1,"text":"Các hợp đồng được đóng bằng cách xem xét các điều khoản và đảm bảo mọi bàn giao và thanh toán đã hoàn tất"},{"level":1,"text":"Đối chiếu ngân sách (budget reconciliation) xác minh rằng các giao dịch khớp với hoạt động hoặc thanh toán thực tế và giải quyết mọi chênh lệch"},{"level":1,"text":"Giai đoạn đóng của dự án thường bị xem nhẹ nhưng rất quan trọng để duy trì các mối quan hệ và bảo vệ công ty"},{"level":2,"text":"Các bàn giao phổ biến trong giai đoạn đóng bao gồm"},{"level":2,"text":"Báo cáo đóng dự án (Project Closure Report)"},{"level":2,"text":"Báo cáo bài học kinh nghiệm (Lessons Learned Report)"},{"level":2,"text":"Tài liệu dự án cuối cùng (Final Project Documentation)"},{"level":2,"text":"Các bàn giao cuối cùng (Final Deliverables)"},{"level":2,"text":"Tài liệu đóng hợp đồng (Contract Closure Documentation)"},{"level":2,"text":"Đối chiếu ngân sách (Budget Reconciliation)"},{"level":2,"text":"Tài liệu bàn giao (Handover Documentation)"},{"level":1,"text":"Không nên bỏ qua các thủ tục đóng dự án đúng đắn vì chúng tối đa hóa lợi ích, tránh hậu quả tiêu cực và cung cấp tài liệu tham khảo cho tương lai"},{"level":1,"text":"Đánh giá dự án (Project Evaluation)"},{"level":2,"text":"Việc đánh giá có phương pháp và khách quan về hiệu suất của dự án để xác định các lĩnh vực cần cải thiện"},{"level":2,"text":"Các loại đánh giá bao gồm tự đánh giá, đánh giá bên ngoài, đánh giá trước dự án, đánh giá liên tục và đánh giá sau dự án"},{"level":1,"text":"Khi lập kế hoạch đánh giá sau dự án, các bước quan trọng bao gồm"},{"level":2,"text":"Tạo kế hoạch đánh giá"},{"level":2,"text":"Chuẩn bị cho đánh giá"},{"level":2,"text":"Thu thập và phân tích dữ liệu"},{"level":2,"text":"Xây dựng báo cáo tóm tắt"},{"level":2,"text":"Tác động (Impact)"},{"level":2,"text":"Điểm mạnh (Strengths)"},{"level":2,"text":"Lĩnh vực cần cải thiện (Areas of improvement)"},{"level":2,"text":"Lập kế hoạch cho các bước tiếp theo"},{"level":1,"text":"Cuộc họp đóng dự án (Project Closure Meeting)"},{"level":2,"text":"Đánh dấu kết thúc của dự án và đóng vai trò là phiên làm việc cuối cùng"},{"level":1,"text":"Báo cáo đóng dự án (Project Closeout Report)"},{"level":2,"text":"Tóm tắt các thảo luận của cuộc họp và dữ liệu hiệu suất bổ sung"},{"level":1,"text":"Hoạt động quản lý nguồn lực (Resource Management Activities)"},{"level":2,"text":"Thu thập phản hồi, thu hồi quyền truy cập, giải phóng nguồn lực, lưu trữ tài liệu và ăn mừng thành công của dự án"}]},{"id":"g151","part":16,"title":"Quản lý thay đổi tổ chức","blocks":[{"level":1,"text":"Quản lý thay đổi tổ chức (Organizational Change Management - OCM)"},{"level":2,"text":"Phương pháp có hệ thống để xây dựng các kế hoạch thay đổi giúp các nhà lãnh đạo thay đổi vượt qua sự kháng cự"},{"level":1,"text":"Sự kháng cự là cơ chế phòng vệ tự nhiên trước bất kỳ sự kiện nào có thể tạo ra sự khó chịu"},{"level":1,"text":"Việc chấp nhận thay đổi (change adoption) là một chỉ số quan trọng đo lường có bao nhiêu người dùng một sản phẩm mới"},{"level":1,"text":"OCM là một chiến lược đảm bảo các dự án có tỷ lệ chấp nhận cao"},{"level":1,"text":"Kế hoạch OCM (OCM Plan)"},{"level":2,"text":"Một phương pháp chiến lược để giúp người dùng thích nghi với các thay đổi"},{"level":2,"text":"Sau đó đội nhóm xây dựng kế hoạch để đơn giản hóa thay đổi, giảm thiểu sự kháng cự và cung cấp hỗ trợ"},{"level":1,"text":"Trong quá trình triển khai OCM, đội dự án cung cấp nhiều hình thức hỗ trợ khác nhau, đóng vai trò là công cụ cho các bên liên quan"},{"level":2,"text":"OCM là một phương pháp tiếp cận được tùy chỉnh và mang tính con người"},{"level":2,"text":"Danh sách các công cụ dưới đây nên được xem như thực đơn hơn là danh sách kiểm tra"},{"level":2,"text":"Đào tạo (Training)"},{"level":2,"text":"Đội nhóm nên xác định các yêu cầu đào tạo cho các người dùng khác nhau, chẳng hạn như cách dùng công cụ, hiểu khái niệm và quản trị quy trình"},{"level":2,"text":"Cơ sở tri thức mới (New Knowledge Base)"},{"level":2,"text":"Cơ sở tri thức (knowledge base - KB) là một hệ thống mô-đun sống động chứa các hướng dẫn, bài viết, hướng dẫn tự phục vụ và mẹo xử lý sự cố cho một sản phẩm"},{"level":2,"text":"Tài liệu (Documentation)"},{"level":2,"text":"Tài liệu bao gồm các hiện vật (artifact) có thể giúp người dùng chấp nhận và duy trì hệ thống mới theo thời gian"},{"level":2,"text":"Quy trình (Processes)"},{"level":2,"text":"Các hướng dẫn được ghi chép mô tả cách hoàn thành công việc"}]},{"id":"g152","part":16,"title":"Kết nối với người dùng cuối","blocks":[{"level":1,"text":"Giao tiếp hiệu quả là một yếu tố quan trọng của quản lý thay đổi tổ chức"},{"level":2,"text":"Điều quan trọng là phải giao tiếp sớm và thường xuyên bằng nhiều kênh khác nhau"},{"level":2,"text":"Email"},{"level":2,"text":"Trò chuyện cá nhân (Personal Conversations)"},{"level":2,"text":"Họp nhóm (Group Meetings)"},{"level":2,"text":"Các buổi đào tạo liên quan (Relevant Training Sessions)"},{"level":1,"text":"Bằng cách duy trì giao tiếp nhất quán, bạn có thể giải quyết các mối lo ngại, xác định các cơ hội cải thiện và hỗ trợ các đội nhóm khi họ thích nghi với các thay đổi"},{"level":1,"text":"Quản lý thay đổi tổ chức đòi hỏi nỗ lực phối hợp để thúc đẩy việc chấp nhận của người dùng thông qua giao tiếp hiệu quả, tài liệu và đào tạo"},{"level":1,"text":"Tỷ lệ phần trăm chấp nhận thay đổi, đo bằng số lượng người dùng hoạt động, có thể đóng vai trò là một chỉ số hữu ích"}]},{"id":"g153","part":16,"title":"Chuẩn bị cho các cuộc họp đánh giá đóng dự án","blocks":[{"level":1,"text":"Trước khi đóng chính thức, một số hoạt động đóng dự án có thể được bắt đầu"},{"level":2,"text":"Chuyển giao các bàn giao"},{"level":2,"text":"Xác thực chúng"},{"level":2,"text":"Đóng hợp đồng"},{"level":2,"text":"Đối chiếu ngân sách"},{"level":1,"text":"Đảm bảo rằng các bên liên quan được thông báo về các tác động của quá trình chuyển đổi"},{"level":2,"text":"Điểm liên hệ mới (New Points of Contact)"},{"level":2,"text":"Thỏa thuận cấp độ dịch vụ (Service License Agreement - SLA)"},{"level":1,"text":"Để bắt đầu quy trình đóng, hãy bắt đầu bằng cách xem xét tài liệu phạm vi dự án"},{"level":2,"text":"Nếu dự án hoàn thành, xác nhận rằng nó đã đạt được các mục tiêu và bàn giao mọi bàn giao yêu cầu"},{"level":2,"text":"Nếu dự án bị tạm dừng hoặc hủy bỏ, chuẩn bị bản tóm tắt nêu rõ những bàn giao nào đã hoàn thành và ở mức độ nào, và truyền đạt điều này đến các bên liên quan"},{"level":1,"text":"Việc lấy được sự phê duyệt bằng văn bản từ mỗi bên liên quan đã xác định rằng dự án đã đáp ứng mọi bàn giao là rất cần thiết"},{"level":1,"text":"Để đóng hợp đồng, điều quan trọng là đảm bảo rằng mọi bên liên quan đã phê duyệt việc đóng dự án"},{"level":2,"text":"Xem xét các điều khoản hợp đồng và đảm bảo mọi bàn giao và hoạt động đã hoàn tất"},{"level":2,"text":"Xác minh rằng mọi đơn mua hàng (purchase order - PO) đã được gửi và hóa đơn đã được thanh toán"},{"level":2,"text":"Xác nhận với các nhà cung cấp rằng họ không mong đợi thêm khoản thanh toán nào, chẳng hạn như hóa đơn chưa thanh toán hoặc báo cáo chi phí còn mở"},{"level":1,"text":"Khi đối chiếu ngân sách, nên áp dụng phân tách nhiệm vụ (separation of duties) bất cứ khi nào có thể"},{"level":2,"text":"Nên dùng một người kiểm tra không phải người khởi tạo, phê duyệt hoặc ghi nhận các chi phí nếu có thể"},{"level":2,"text":"Đối chiếu (Reconciliation)"},{"level":2,"text":"Một quy trình xác minh trong đó mỗi giao dịch trong ngân sách được xác nhận khớp với một hoạt động hoặc thanh toán thực tế"},{"level":2,"text":"Xác minh rằng chi phí nguồn lực là chính xác cho các hoạt động của dự án và xác nhận rằng mọi PO đều được tính vào ngân sách dự án"},{"level":2,"text":"Các chênh lệch nên được điều tra và giải quyết"}]},{"id":"g154","part":16,"title":"Tổng quan giai đoạn đóng","blocks":[{"level":1,"text":"PM đóng vai trò quan trọng như động lực thúc đẩy việc khởi xướng mọi hoạt động đóng"},{"level":1,"text":"Mặc dù giai đoạn đóng có vẻ đơn giản, điều quan trọng là phải theo dõi đầy đủ mọi công việc cần thiết"},{"level":2,"text":"Hoàn tất tài liệu"},{"level":2,"text":"Gắn kết các đầu mối còn dang dở (Tie up loose ends)"},{"level":2,"text":"Chính thức kết thúc dự án"},{"level":1,"text":"Điều quan trọng cần lưu ý là các bên liên quan đã đang gặt hái lợi ích của dự án, và các thành viên đội nhóm đã chuyển hướng tinh thần sang dự án tiếp theo"},{"level":1,"text":"PM phải nhận biết khi nào dự án sẵn sàng đóng"},{"level":2,"text":"Các mục tiêu dự án đã được đáp ứng"},{"level":2,"text":"Dự án bị hủy bỏ"},{"level":2,"text":"Dự án bị tạm dừng"},{"level":1,"text":"Các bàn giao cụ thể trong giai đoạn đóng của dự án có thể khác nhau tùy thuộc vào bản chất của dự án và quy trình của tổ chức"},{"level":1,"text":"Một số bàn giao phổ biến thường được bao gồm trong giai đoạn đóng của dự án"},{"level":2,"text":"Báo cáo đóng dự án (Project Closure Report)"},{"level":2,"text":"Ghi lại trạng thái cuối cùng của dự án và cung cấp cái nhìn tổng quan về các thành tựu và thách thức của nó"},{"level":2,"text":"Nó bao gồm các thông tin sau"},{"level":2,"text":"Mục tiêu (Objectives)"},{"level":2,"text":"Phạm vi (Scope)"},{"level":2,"text":"Ngân sách (Budget)"},{"level":2,"text":"Tiến độ (Schedule)"},{"level":2,"text":"Báo cáo bài học kinh nghiệm (Lessons Learned Report)"},{"level":2,"text":"Phác thảo các thành công và thất bại của dự án"},{"level":2,"text":"Tài liệu dự án cuối cùng (Final Project Documentation)"},{"level":2,"text":"Bao gồm mọi tài liệu dự án"},{"level":2,"text":"Kế hoạch dự án (Project Plans)"},{"level":2,"text":"Tiến độ (Schedules)"},{"level":2,"text":"Báo cáo trạng thái (Status Reports)"},{"level":2,"text":"Biên bản họp (Meeting Minutes)"},{"level":2,"text":"Các thông tin khác liên quan đến dự án (Other Project-Related Information)"},{"level":2,"text":"Các bàn giao cuối cùng (Final Deliverables)"},{"level":2,"text":"Các dịch vụ được tạo ra như kết quả của dự án"},{"level":2,"text":"Tài liệu đóng hợp đồng (Contract Closure Documentation)"},{"level":2,"text":"Bao gồm mọi giấy tờ cần thiết để chính thức đóng các hợp đồng với nhà cung cấp, nhà thầu hoặc các bên thứ ba khác"},{"level":2,"text":"Đối chiếu ngân sách (Budget Reconciliation)"},{"level":2,"text":"Bao gồm việc so sánh ngân sách dự án cuối cùng với chi phí thực tế và đảm bảo mọi chi phí đều được hạch toán"},{"level":2,"text":"Tài liệu bàn giao (Handover Documentation)"},{"level":2,"text":"Bao gồm mọi thông tin và hướng dẫn cần thiết cho đội vận hành hoặc các bên liên quan khác sẽ tiếp quản việc hỗ trợ và bảo trì liên tục của dự án"},{"level":1,"text":"Đừng bỏ qua các thủ tục đóng dự án đúng đắn của một dự án"}]},{"id":"g155","part":16,"title":"Tổng quan đánh giá dự án","blocks":[{"level":1,"text":"Đánh giá dự án là việc đánh giá có phương pháp và khách quan về hiệu suất của một dự án"},{"level":1,"text":"Các đánh giá dự án cải thiện hiệu suất của dự án hiện tại và toàn bộ hệ thống quản lý dự án"},{"level":1,"text":"Để đảm bảo các bài học kinh nghiệm mang lại lợi ích cho các dự án tương lai, dữ liệu nên được thu thập, ghi chép và chia sẻ một cách nhất quán"},{"level":1,"text":"Các đánh giá tạo ra một dự án hấp dẫn hơn bằng cách thu thập phản hồi từ các bên liên quan"},{"level":1,"text":"Tham gia vào các đánh giá dự án đòi hỏi sự suy ngẫm và tư duy phản biện"},{"level":1,"text":"Một số loại đánh giá mà quản lý dự án có thể sử dụng"},{"level":2,"text":"Tự đánh giá (Self-Evaluation)"},{"level":2,"text":"Một hoạt động bao gồm tự suy ngẫm để xác định các lĩnh vực cần cải thiện"},{"level":2,"text":"Đánh giá bên ngoài (External Evaluation)"},{"level":2,"text":"Một đánh giá do bên thứ ba thực hiện để đưa ra đánh giá khách quan về một sản phẩm, dịch vụ hoặc dự án"},{"level":2,"text":"Các đánh giá bên ngoài mang lại góc nhìn mới và xác định các điểm mù hoặc điểm yếu có thể đã bị bỏ sót nội bộ"},{"level":2,"text":"Đánh giá trước dự án (Pre-Project Evaluation)"},{"level":2,"text":"Một đánh giá về một ý tưởng dự án để xác định xem nó có đáng theo đuổi không"},{"level":2,"text":"Các đánh giá trước dự án tránh lãng phí nguồn lực vào các dự án không khả thi"},{"level":2,"text":"Đánh giá liên tục (Ongoing Evaluation)"},{"level":2,"text":"Các đánh giá được thực hiện trong suốt vòng đời của dự án để đánh giá tiến độ và xác định các cơ hội cải thiện"},{"level":2,"text":"Đánh giá sau dự án (Post-Project Evaluation)"},{"level":2,"text":"Một đánh giá được thực hiện sau khi hoàn thành dự án để đánh giá kết quả và tác động của nó"},{"level":2,"text":"Các đánh giá sau dự án rất quan trọng để học hỏi từ thành công và thất bại và cải thiện các dự án tương lai"},{"level":2,"text":"Khi chúng ta bắt đầu lập kế hoạch đánh giá sau dự án, có một số bước liên quan"},{"level":2,"text":"Xây dựng kế hoạch đánh giá"},{"level":2,"text":"Xác định các lĩnh vực quan tâm"},{"level":2,"text":"Chuẩn bị cho đánh giá"},{"level":2,"text":"Liệt kê mọi điểm dữ liệu và chỉ số hiệu suất"},{"level":2,"text":"Thu thập và phân tích dữ liệu"},{"level":2,"text":"Triển khai kế hoạch đánh giá và đặt giới hạn thời gian cho việc thu thập dữ liệu"},{"level":2,"text":"Xây dựng báo cáo tóm tắt"},{"level":2,"text":"Tạo một báo cáo súc tích cung cấp kết quả đánh giá dự án"},{"level":2,"text":"Bản tóm tắt bao gồm phản hồi của các bên liên quan để đánh giá dự án và tác động thực tế của nó"},{"level":2,"text":"Lập kế hoạch cho các bước tiếp theo"},{"level":2,"text":"Chia sẻ báo cáo với đội dự án và các bên liên quan, xác định các lĩnh vực cần cải thiện và phân công trách nhiệm"}]},{"id":"g156","part":16,"title":"Cuộc họp đóng dự án","blocks":[{"level":1,"text":"Cuộc họp đóng dự án (Project Closure Meeting)"},{"level":2,"text":"Đánh dấu kết thúc của dự án và đóng vai trò là phiên làm việc cuối cùng"},{"level":1,"text":"Trong cuộc họp, đội nhóm thảo luận về dự án bao gồm"},{"level":2,"text":"Các thành tựu (Accomplishments)"},{"level":2,"text":"Các thất bại (Failures)"},{"level":2,"text":"Các thách thức (Challenges)"},{"level":1,"text":"Điều quan trọng là ghi lại mọi ý tưởng được thảo luận trong cuộc họp để xác định cách áp dụng chúng vào các dự án tương lai"},{"level":1,"text":"Chương trình làm việc của một cuộc họp dự án thường bao gồm một số hạng mục bao quát các khía cạnh khác nhau của dự án"},{"level":2,"text":"Tổng quan dự án (Project Overview)"},{"level":2,"text":"Liệt kê các mục tiêu, mục đích và tiêu chí thành công của dự án"},{"level":2,"text":"Điểm nổi bật của dự án (Project Highlights)"},{"level":2,"text":"Phác thảo các thành tựu đáng kể của đội dự án"},{"level":2,"text":"Các thách thức của dự án cũng được thảo luận, vì chúng là cơ hội học hỏi tuyệt vời cho đội dự án và các đội khác có thể gặp phải các vấn đề tương tự"},{"level":2,"text":"Tính minh bạch có lợi cho mọi người, vì vậy hạng mục này xác định các thách thức của dự án và cách đội nhóm đã vượt qua chúng"},{"level":2,"text":"Các vấn đề về quy trình (Process Issues)"},{"level":2,"text":"Các vấn đề kỹ thuật (Technical Issues)"},{"level":2,"text":"Các chỉ số hiệu suất kém (Underperforming Metrics)"},{"level":2,"text":"Hội thảo bài học kinh nghiệm (Lessons Learned Workshop)"},{"level":2,"text":"Là hạng mục lớn nhất trong chương trình, chiếm khoảng một nửa thời gian họp đã lên lịch"},{"level":2,"text":"Một phiên học bài học kinh nghiệm cuối dự án được tổ chức trong cuộc họp này"},{"level":2,"text":"Hoạt động đóng dự án này nhằm xác định các cách cải thiện các dự án tương lai và còn được gọi là \"post-mortem,\" \"project retrospective,\" hoặc \"project review\""},{"level":2,"text":"Trong phiên học bài học kinh nghiệm, PM thảo luận về các chỉ số hiệu suất cuối cùng của dự án, bao gồm chi phí, ngân sách và tiến độ"},{"level":2,"text":"Ngoài ra, nhóm thảo luận về phản hồi của các bên liên quan, các chủ đề đánh giá dự án còn lại và bất kỳ suy ngẫm nào khác về dự án"}]},{"id":"g157","part":16,"title":"Báo cáo đóng dự án","blocks":[{"level":1,"text":"Sau khi cuộc họp đóng kết thúc, quản lý dự án (PM) phải lập một báo cáo đóng dự án phác thảo các thảo luận của cuộc họp và bao gồm dữ liệu hiệu suất bổ sung"},{"level":1,"text":"Báo cáo đóng dự án (Project Closeout Report)"},{"level":2,"text":"Một bản tóm tắt toàn diện về toàn bộ dự án và đóng vai trò là yêu cầu chính thức xin phê duyệt đóng dự án (sign-off)"},{"level":1,"text":"Một báo cáo đóng dự án thường bao gồm các nội dung sau"},{"level":2,"text":"Tổng quan dự án (Project Overview)"},{"level":2,"text":"Một mô tả ngắn gọn về dự án, bao gồm các mục tiêu, mục đích và phạm vi"},{"level":2,"text":"Các bàn giao (Deliverables)"},{"level":2,"text":"Một danh sách mọi bàn giao đã hoàn thành trong dự án, cùng với các chi tiết liên quan"},{"level":2,"text":"Tiêu chí thành công (Success Criteria)"},{"level":2,"text":"Một bản tóm tắt về cách dự án đáp ứng các tiêu chí thành công, bao gồm mọi chỉ số hoặc KPI được dùng để đo lường thành công"},{"level":2,"text":"Điểm nổi bật của dự án (Project Highlights)"},{"level":2,"text":"Một phần phác thảo các thành tựu đáng kể của đội dự án, bao gồm mọi cải tiến quy trình hoặc phương pháp bàn giao thành công"},{"level":2,"text":"Các thách thức của dự án (Project Challenges)"},{"level":2,"text":"Một mô tả về các thách thức của dự án và cách đội nhóm đã vượt qua chúng, cùng với bất kỳ bài học kinh nghiệm nào"},{"level":2,"text":"Cân nhắc tương lai (Future Considerations)"},{"level":2,"text":"Các ý tưởng cho cải tiến tương lai hoặc công việc tiếp theo, cùng với các hạng mục hành động và ngày đến hạn"},{"level":2,"text":"Bài học kinh nghiệm (Lessons Learned)"},{"level":2,"text":"Một bản tóm tắt các bài học kinh nghiệm trong suốt dự án, bao gồm phản hồi từ các bên liên quan và khách hàng"},{"level":2,"text":"Đánh giá dự án (Project Evaluation)"},{"level":2,"text":"Một đánh giá cuối cùng về hiệu suất của dự án, bao gồm chi phí, ngân sách và tiến độ"},{"level":2,"text":"Yêu cầu phê duyệt (Sign-off Request)"},{"level":2,"text":"Một yêu cầu gửi đến các bên liên quan và nhà tài trợ của dự án để ký duyệt báo cáo, chính thức đóng dự án"}]},{"id":"g158","part":16,"title":"Hoàn tất các hoạt động quản lý nguồn lực","blocks":[{"level":1,"text":"Quản lý nguồn lực hiệu quả giúp quản lý dự án lập kế hoạch, phân bổ và tối ưu hóa nguồn lực để đảm bảo chúng được sử dụng hiệu quả và hiệu lực trong suốt vòng đời dự án"},{"level":1,"text":"PM có thể xác định và xử lý mọi ràng buộc nguồn lực hoặc điểm nghẽn tiềm ẩn"},{"level":1,"text":"Việc hoàn tất các hoạt động quản lý nguồn lực giúp quản lý dự án giám sát và kiểm soát việc sử dụng nguồn lực"},{"level":2,"text":"Điều này giúp tối đa hóa năng suất, giảm lãng phí và tăng lợi nhuận"},{"level":1,"text":"Nhắc lại, việc hoàn tất các hoạt động quản lý nguồn lực là rất quan trọng cho thành công của dự án"},{"level":2,"text":"Nó giúp quản lý dự án tối ưu hóa việc sử dụng nguồn lực, giảm thiểu rủi ro dự án và đảm bảo dự án được bàn giao đúng hạn, trong ngân sách và đạt các tiêu chuẩn chất lượng yêu cầu"},{"level":2,"text":"Chúng ta nên làm gì để thực hiện điều này?"},{"level":2,"text":"Thu thập phản hồi từ các bên liên quan"},{"level":2,"text":"Thu hồi các quyền truy cập (Removes accesses)"},{"level":2,"text":"Giải phóng nguồn lực (Release resources)"},{"level":2,"text":"Lưu trữ tài liệu (Archive documentation)"},{"level":2,"text":"Ăn mừng (Celebrate)"},{"level":1,"text":"Trong giai đoạn đóng, thu thập phản hồi từ cả thành viên đội nhóm và các bên liên quan"},{"level":2,"text":"Khảo sát là một cách hiệu quả để thu thập phản hồi cuối cùng vì các bên liên quan gần đây đã cung cấp phản hồi tương tác nhiều hơn trong cuộc họp đóng dự án"},{"level":2,"text":"Phản hồi này nên tập trung nhiều hơn vào đánh giá khách quan và nhận xét cuối cùng, và một khảo sát ẩn danh có thể tạo ra phản hồi minh bạch nhất"},{"level":1,"text":"Cuối dự án, điều quan trọng là loại bỏ các quyền truy cập không cần thiết để ngăn ngừa các vấn đề bảo mật và kiểm soát chi phí"},{"level":1,"text":"Quản lý truy cập là một chức năng quan trọng trong hầu hết các tổ chức, và các công việc này có thể được giao cho các nhóm chịu trách nhiệm"},{"level":1,"text":"PM cũng nên kiểm tra mức độ truy cập của các thành viên đội nhóm, các bên liên quan và nhà cung cấp, và xác định họ có quyền truy cập vào những nguồn lực nào và những nguồn lực nào họ không còn cần"},{"level":1,"text":"Chúng ta cần giải phóng các nguồn lực và chính thức giải tán đội dự án"},{"level":2,"text":"Công nhận việc kết thúc công việc của dự án với mọi người làm việc trong dự án, bao gồm thành viên đội nhóm, nhà thầu và nhà cung cấp"},{"level":1,"text":"Các tệp dự án sẽ được chuyển vào kho lưu trữ của tổ chức, vì vậy việc giữ một bản sao của bất kỳ tài liệu nào sẽ hữu ích cho các dự án tương lai là một ý hay"},{"level":2,"text":"Giữ một bản sao hoặc danh sách cập nhật liên tục các bài học kinh nghiệm và duy trì các bản sao của mẫu biểu, quy trình tái sử dụng và danh sách kiểm tra"},{"level":1,"text":"Hãy dành thời gian để ghi nhận những đóng góp của đội nhóm và ăn mừng thành công của dự án Conclusion"}]},{"id":"g159","part":16,"title":"Kết luận","blocks":[{"level":1,"text":"4 lĩnh vực (domain) của Project+"},{"level":2,"text":"Lĩnh vực 1: Khái niệm quản lý dự án (Project Management Concepts)"},{"level":2,"text":"Chiếm 33% bài thi"},{"level":2,"text":"Lĩnh vực 2: Các giai đoạn vòng đời dự án (Project Life Cycle Phases)"},{"level":2,"text":"Chiếm 30% bài thi"},{"level":2,"text":"Lĩnh vực 3: Công cụ và tài liệu (Tools and Documentation)"},{"level":2,"text":"Chiếm 19% bài thi"},{"level":2,"text":"Lĩnh vực 4: Kiến thức CNTT cơ bản và quản trị (IT Basics and Governance)"},{"level":2,"text":"Chiếm 18% bài thi"},{"level":1,"text":"Làm thế nào để đăng ký và lên lịch thi?"},{"level":2,"text":"Pearson VUE"},{"level":2,"text":"Bạn có thể thi tại bất kỳ trung tâm khảo thí Pearson VUE nào trên toàn thế giới, tại trung tâm địa phương hoặc thi trực tuyến"},{"level":2,"text":"Bạn có thể mua voucher thi bằng cách vào thẳng Pearson Vue khi lên lịch thi tại pearsonvue.com, hoặc vào cửa hàng voucher tại lpi.org để mua từ cửa hàng trực tuyến của họ"},{"level":2,"text":"Pearson VUE và LPI hiện đã tạo ra khả năng để bạn thi chứng chỉ trực tuyến ngay tại nhà hoặc văn phòng, sử dụng hệ thống kiểm tra trực tuyến Pearson VUE OnVue"},{"level":2,"text":"Dion Training"},{"level":2,"text":"Nếu bạn muốn mua trước voucher thi trước khi lên lịch thi, bạn thực sự có thể tiết kiệm 10% giá bằng cách vào website của chúng tôi tại diontraining.com/vouchers"},{"level":2,"text":"Hiện tại, chúng tôi có voucher cho hơn 50 quốc gia trên toàn thế giới, và chúng tôi đang bổ sung các quốc gia mọi lúc"},{"level":2,"text":"Là Đối tác Bạch kim của LPI, chúng tôi nhận được mức giá chiết khấu đặc biệt cho các voucher thi này và chúng tôi chuyển khoản tiết kiệm đó cho học viên khi họ đặt mua voucher thi từ chúng tôi"},{"level":1,"text":"Năm mẹo hàng đầu để tăng điểm thi"},{"level":2,"text":"Dùng tờ ghi chú (cheat sheet)"},{"level":2,"text":"Bạn thực sự không được phép mang bất cứ thứ gì vào phòng thi, nhưng nếu bạn thi tại trung tâm khảo thí địa phương, họ sẽ đưa cho bạn bảng trắng hoặc tờ xóa khô có kích thước bằng một tờ giấy thông thường"},{"level":2,"text":"Sau khi đồng hồ thi bắt đầu, bạn có thể ghi nhớ (brain-dump) bất cứ thứ gì bạn muốn lên tờ giấy đó"},{"level":2,"text":"Hãy dùng tờ giấy và dành 1-2 phút đầu viết ra những điều quan trọng mà bạn có thể quên sau này"},{"level":2,"text":"Bỏ qua các câu hỏi gây khó khăn cho bạn"},{"level":2,"text":"Nếu bạn thấy mình đang vật lộn với một câu hỏi thực sự khó, hãy đánh dấu để xem lại và bỏ qua nó"},{"level":2,"text":"Các học viên làm vậy thường tăng điểm ít nhất 5% đến 10% so với các bạn cố làm các mô phỏng ngay từ đầu bài thi"},{"level":2,"text":"Hãy đoán (Take a guess)"},{"level":2,"text":"Nếu bạn không chắc chắn, tôi muốn bạn đoán trong số các lựa chọn trả lời có thể"},{"level":2,"text":"Không có hình phạt nào cho việc đoán sai trong bài thi"},{"level":2,"text":"Nếu bạn không chắc về đáp án đúng, hãy cố loại bỏ càng nhiều lựa chọn càng tốt và đoán trong số các lựa chọn trả lời còn lại"},{"level":2,"text":"Chọn thời điểm tốt nhất cho kỳ thi của bạn"},{"level":2,"text":"Chọn thời gian trong ngày phù hợp nhất với bạn"},{"level":2,"text":"Đừng cố nhét kỳ thi vào sau một ngày làm việc dài ở văn phòng"},{"level":2,"text":"Hãy tự tin"},{"level":2,"text":"Bạn làm được mà!"},{"level":2,"text":"Bạn nên biết rằng mình sẽ đậu!"},{"level":2,"text":"Bạn hẳn đã học mọi thông tin trong khóa học này, bạn đã xem các video, bạn đã làm các bài kiểm tra, bạn đã học các ghi chú học tập có thể tải xuống"},{"level":2,"text":"Nếu bạn không tự tin ngay bây giờ, hãy đợi vài ngày rồi mới lên lịch thi"},{"level":2,"text":"Hãy làm nhiều bài thi thử và xây dựng sự tự tin"},{"level":1,"text":"Khi làm bài thi thử, mục tiêu của bạn không phải là ghi nhớ đáp án"},{"level":2,"text":"Bạn cần hiểu tại sao đáp án đúng lại đúng và các đáp án sai lại sai"},{"level":1,"text":"Chúc may mắn, và chúng tôi hy vọng được gặp lại bạn trong một khóa học tương lai khi bạn tiếp tục tiến lên trong sự nghiệp quản lý dự án, CNTT hoặc an ninh mạng và tiếp tục leo lên thang chứng chỉ CompTIA!"}]});
